package com.example.starter.film.domain;

import java.time.Instant;

/**
 * 馆藏影片；按计划包含固定数量的片段，片段按 1..N 序号组成整部影片。
 *
 * @param id               影片主键
 * @param code             影片业务编号，全局唯一
 * @param plannedSegments  计划片段总数，审核时必须每段都有有效提交
 * @param createdAt        创建时间，UTC 时间线
 */
public record Film(long id, String code, int plannedSegments, Instant createdAt) {
}

package com.example.starter.film.domain;

import java.time.Instant;

/**
 * 单个片段的一次修复提交；同一 {@code segmentNo} 的记录只追加、不改写，按 {@code versionNo} 组成版本链。
 *
 * @param id               版本记录主键
 * @param filmId           所属影片 ID
 * @param segmentNo        片段序号，从 1 开始
 * @param versionNo        该片段内的版次，首版为 1，逐次加 1
 * @param contentDigest    内容摘要（格式：sha256: 加 64 位十六进制）
 * @param basedOnVersion   本次提交基于的当前版次；首版为 null，其余必须等于提交前的最新版次
 * @param requestId        幂等请求号；同一影片内唯一，重复提交用于去重
 * @param createdAt        提交时间，UTC 时间线
 */
public record SegmentVersion(long id, long filmId, int segmentNo, int versionNo, String contentDigest,
                             Integer basedOnVersion, String requestId, Instant createdAt) {
}

package com.example.starter.film.domain;

/**
 * 母版状态；审核通过后为 {@link #APPROVED}，撤销后为 {@link #REVOKED}。
 * 撤销只阻止新的交付，已生成的交付回执与母版快照不受影响。
 */
public enum MasterStatus {

    /** 审核通过，可被交付引用。 */
    APPROVED,

    /** 已撤销，不允许新的交付。 */
    REVOKED
}

package com.example.starter.film.domain;

import java.time.Instant;

/**
 * 整片审核生成的固定母版；母版编号一经生成不可变，不随后续工作版更新而变化。
 *
 * @param id          母版主键
 * @param filmId      所属影片 ID
 * @param masterNo    不可变母版编号，全局唯一，交付只引用该编号
 * @param status      母版状态
 * @param createdAt   审核通过时间，UTC 时间线
 * @param revokedAt   撤销时间，UTC 时间线；未撤销时为 null
 */
public record Master(long id, long filmId, String masterNo, MasterStatus status,
                     Instant createdAt, Instant revokedAt) {
}

package com.example.starter.film.domain;

/**
 * 母版在审核通过瞬间固定下来的单个片段引用；版次与摘要成对冻结，不读取后来更新的工作版。
 *
 * @param masterId      所属母版 ID
 * @param segmentNo     片段序号
 * @param versionNo     固定的片段版次
 * @param contentDigest 固定的片段内容摘要
 */
public record MasterSegment(long masterId, int segmentNo, int versionNo, String contentDigest) {
}

package com.example.starter.film.domain;

import java.time.Instant;

/**
 * 交付回执；交付成功即不可变，保存曾交付母版的片段快照 JSON。
 *
 * @param id           回执主键
 * @param filmId       所属影片 ID
 * @param receiptNo    回执编号，全局唯一；交付重试必须返回原回执，不生成第二张
 * @param masterNo     交付引用的不可变母版编号
 * @param requestId    幂等请求号；同一影片内唯一
 * @param snapshotJson 交付瞬间固定的母版片段快照（序号、版次、摘要），母版撤销后仍保留
 * @param createdAt    交付时间，UTC 时间线
 */
public record DeliveryReceipt(long id, long filmId, String receiptNo, String masterNo, String requestId,
                              String snapshotJson, Instant createdAt) {
}

package com.example.starter.film.api;

import org.springframework.http.HttpStatus;

/**
 * 业务异常；携带 HTTP 状态码与稳定错误码，由统一异常处理器转换为响应体。
 */
public class ApiException extends RuntimeException {

    private final HttpStatus status;
    private final String code;

    public ApiException(HttpStatus status, String code, String message) {
        super(message);
        this.status = status;
        this.code = code;
    }

    public HttpStatus getStatus() {
        return status;
    }

    public String getCode() {
        return code;
    }
}

