package com.example.starter.film.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Positive;

/**
 * 片段修复提交请求。
 *
 * @param segmentNo      片段序号，从 1 开始，不得超出影片计划片段数
 * @param contentDigest  内容摘要，格式必须为 {@code sha256:<64位十六进制>}
 * @param basedOnVersion 基于的当前版次；首版为 null，续版必须等于该片段提交前的最新版次
 * @param requestId      客户端幂等请求号
 */
public record SegmentSubmitRequest(
        @NotNull @Positive Integer segmentNo,
        @NotBlank
        @Pattern(regexp = "sha256:[0-9a-fA-F]{64}", message = "内容摘要必须为 sha256: 加 64 位十六进制")
        String contentDigest,
        Integer basedOnVersion,
        @NotBlank String requestId) {
}

package com.example.starter.film.api;

import jakarta.validation.constraints.NotBlank;

/**
 * 整片审核请求；审核要求该影片所有计划片段均已有有效提交。
 *
 * @param requestId 客户端幂等请求号
 */
public record ReviewRequest(@NotBlank String requestId) {
}

package com.example.starter.film.api;

import jakarta.validation.constraints.NotBlank;

/**
 * 交付请求；只引用审核通过的不可变母版编号。
 *
 * @param masterNo  母版编号
 * @param requestId 客户端幂等请求号
 */
public record DeliveryRequest(@NotBlank String masterNo, @NotBlank String requestId) {
}

package com.example.starter.film.api;

import com.example.starter.film.domain.SegmentVersion;

/**
 * 片段提交结果。
 *
 * @param segmentNo      片段序号
 * @param versionNo      本次生成的版次
 * @param contentDigest  内容摘要
 * @param basedOnVersion 基于的版次；首版为 null
 * @param requestId      幂等请求号
 * @param replayed       true 表示这是同一 requestId 的重复请求，返回的是原有版次而非新提交
 */
public record SegmentSubmitResponse(int segmentNo, int versionNo, String contentDigest,
                                    Integer basedOnVersion, String requestId, boolean replayed) {

    public static SegmentSubmitResponse from(SegmentVersion v, boolean replayed) {
        return new SegmentSubmitResponse(v.segmentNo(), v.versionNo(), v.contentDigest(),
                v.basedOnVersion(), v.requestId(), replayed);
    }
}

package com.example.starter.film.api;

import java.util.List;

/**
 * 母版中单个片段的固定引用。
 */
public record MasterSegmentView(int segmentNo, int versionNo, String contentDigest) {
}

package com.example.starter.film.api;

import com.example.starter.film.domain.MasterStatus;

import java.time.Instant;
import java.util.List;

/**
 * 整片审核结果。
 *
 * @param masterNo  不可变母版编号
 * @param status    母版状态
 * @param segments  审核瞬间固定的每段版次与摘要，按序号升序
 * @param createdAt 审核通过时间，UTC
 * @param replayed  true 表示同一 requestId 的重复审核返回了已存在母版
 */
public record ReviewResponse(String masterNo, MasterStatus status, List<MasterSegmentView> segments,
                             Instant createdAt, boolean replayed) {
}

package com.example.starter.film.api;

import java.time.Instant;
import java.util.List;

/**
 * 交付回执结果。
 *
 * @param receiptNo  回执编号
 * @param masterNo   交付引用的母版编号
 * @param requestId  幂等请求号
 * @param segments   曾交付母版的片段快照，按序号升序
 * @param createdAt  交付时间，UTC
 * @param replayed   true 表示交付重试返回原回执，未生成第二张回执
 */
public record DeliveryResponse(String receiptNo, String masterNo, String requestId,
                               List<MasterSegmentView> segments, Instant createdAt, boolean replayed) {
}

package com.example.starter.film.api;

import java.time.Instant;

/**
 * 交付回执视图，用于查询。
 */
public record ReceiptView(String receiptNo, String masterNo, String requestId,
                          String snapshotJson, Instant createdAt) {
}

package com.example.starter.film.api;

import com.example.starter.film.domain.MasterStatus;

import java.time.Instant;
import java.util.List;

/**
 * 母版视图，用于查询。
 */
public record MasterView(String masterNo, MasterStatus status, List<MasterSegmentView> segments,
                         Instant createdAt, Instant revokedAt) {
}

package com.example.starter.film.api;

import com.example.starter.film.domain.SegmentVersion;

import java.util.List;

/**
 * 影片查询视图：片段版次链、母版引用、交付回执。
 */
public record FilmView(String code, int plannedSegments,
                       List<SegmentVersion> segmentChain,
                       List<MasterView> masters,
                       List<ReceiptView> receipts) {
}

