package com.example.starter.film;

import com.example.starter.film.api.ApiException;
import com.example.starter.film.api.ReviewRequest;
import com.example.starter.film.api.SegmentSubmitRequest;
import com.example.starter.film.api.SegmentSubmitResponse;
import com.example.starter.film.domain.Film;
import com.example.starter.film.domain.SegmentVersion;
import com.example.starter.film.repo.FilmRepository;
import com.example.starter.film.service.FilmServiceImpl;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.http.HttpStatus;

import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import java.util.List;
import java.util.Optional;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.ArgumentMatchers.anyLong;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * 不依赖数据库的服务规则单元测试：用 mock 仓储驱动幂等与缺段分支。
 */
class FilmServiceUnitTest {

    private FilmRepository repository;
    private FilmServiceImpl service;

    private final Film film = new Film(7L, "F-UNIT", 2, Instant.parse("2026-10-01T00:00:00Z"));

    @BeforeEach
    void setUp() {
        repository = mock(FilmRepository.class);
        when(repository.findFilmByCode("F-UNIT")).thenReturn(Optional.of(film));
        service = new FilmServiceImpl(repository, new ObjectMapper(),
                Clock.fixed(Instant.parse("2026-10-01T08:00:00Z"), ZoneOffset.UTC));
    }

    private SegmentSubmitRequest request(int segmentNo, String digest, Integer basedOn, String requestId) {
        return new SegmentSubmitRequest(segmentNo, digest, basedOn, requestId);
    }

    @Test
    void 同requestId同参重放原记录_不写入新版本() {
        SegmentVersion existing = new SegmentVersion(
                1L, 7L, 1, 1, TestData.digest("a"), null, "rid", Instant.parse("2026-10-01T01:00:00Z"));
        when(repository.findSegmentRequest(7L, "rid")).thenReturn(Optional.of(existing));

        SegmentSubmitResponse response = service.submitSegment("F-UNIT",
                request(1, TestData.digest("a"), null, "rid"));

        assertTrue(response.replayed());
        assertEquals(1, response.versionNo());
        verify(repository, never()).insertSegmentVersion(
                anyLong(), anyInt(), anyInt(), any(), any(), any(), any());
    }

    @Test
    void 同requestId异参抛409() {
        SegmentVersion existing = new SegmentVersion(
                1L, 7L, 1, 1, TestData.digest("a"), null, "rid", Instant.parse("2026-10-01T01:00:00Z"));
        when(repository.findSegmentRequest(7L, "rid")).thenReturn(Optional.of(existing));

        ApiException ex = assertThrows(ApiException.class, () -> service.submitSegment("F-UNIT",
                request(1, TestData.digest("b"), null, "rid")));
        assertEquals(HttpStatus.CONFLICT, ex.getStatus());
        assertEquals("IDEMPOTENCY_CONFLICT", ex.getCode());
    }

    @Test
    void 缺段审核422_不插入母版() {
        when(repository.findMasterByReviewRequest(anyLong(), any())).thenReturn(Optional.empty());
        when(repository.findLatestVersions(7L)).thenReturn(List.of());

        ApiException ex = assertThrows(ApiException.class,
                () -> service.review("F-UNIT", new ReviewRequest("rv")));
        assertEquals(HttpStatus.UNPROCESSABLE_ENTITY, ex.getStatus());
        assertEquals("MISSING_SEGMENTS", ex.getCode());
        verify(repository, never()).insertMaster(
                anyLong(), any(), any(), any());
    }

    @Test
    void 基于旧版次409() {
        SegmentVersion latest = new SegmentVersion(
                2L, 7L, 1, 2, TestData.digest("v2"), 1, "rid2", Instant.parse("2026-10-01T02:00:00Z"));
        when(repository.findLatestSegment(7L, 1)).thenReturn(Optional.of(latest));

        ApiException ex = assertThrows(ApiException.class, () -> service.submitSegment("F-UNIT",
                request(1, TestData.digest("v3"), 1, "rid3")));
        assertEquals(HttpStatus.CONFLICT, ex.getStatus());
        assertEquals("VERSION_CONFLICT", ex.getCode());
        verify(repository, never()).insertSegmentVersion(
                anyLong(), anyInt(), anyInt(), any(), any(), any(), any());
    }

    @Test
    void 首版省略basedOn成功写入版次1() {
        when(repository.findSegmentRequest(7L, "new-rid")).thenReturn(Optional.empty());
        when(repository.findLatestSegment(7L, 1)).thenReturn(Optional.empty());
        SegmentVersion saved = new SegmentVersion(
                3L, 7L, 1, 1, TestData.digest("v1"), null, "new-rid",
                Instant.parse("2026-10-01T08:00:00Z"));
        when(repository.findLatestSegment(7L, 1)).thenReturn(Optional.of(saved));

        SegmentSubmitResponse response = service.submitSegment("F-UNIT",
                request(1, TestData.digest("v1"), null, "new-rid"));
        assertEquals(1, response.versionNo());
        verify(repository).insertSegmentVersion(eq(7L), eq(1), eq(1),
                eq(TestData.digest("v1")), eq(null), eq("new-rid"), any(Instant.class));
    }
}

package com.example.starter.film;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.MvcResult;

import java.util.Map;
import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

/**
 * HTTP 层真实 H2 测试：验证状态码（201/422/409/404）、幂等重放与查询结构。
 */
@SpringBootTest
@AutoConfigureMockMvc
class FilmControllerWebTest {

    @Autowired
    private MockMvc mockMvc;

    @Autowired
    private ObjectMapper objectMapper;

    @Autowired
    private JdbcTemplate jdbc;

    private String code;

    @BeforeEach
    void clean() {
        jdbc.update("DELETE FROM delivery_receipt");
        jdbc.update("DELETE FROM master_segment");
        jdbc.update("DELETE FROM master");
        jdbc.update("DELETE FROM segment_version");
        jdbc.update("DELETE FROM film");
        code = "W-" + UUID.randomUUID().toString().substring(0, 8);
    }

    private String json(Object body) throws Exception {
        return objectMapper.writeValueAsString(body);
    }

    @Test
    void 完整业务链路的HTTP状态与报文() throws Exception {
        // 注册影片（两段）。
        mockMvc.perform(post("/api/films")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(json(Map.of("code", code, "plannedSegments", 2))))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.code").value(code));

        // 摘要格式错误 -> 422。
        mockMvc.perform(post("/api/films/" + code + "/segments")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(json(Map.of("segmentNo", 1, "contentDigest", "sha256:zz",
                                "requestId", "bad"))))
                .andExpect(status().isUnprocessableEntity())
                .andExpect(jsonPath("$.code").value("VALIDATION_FAILED"));

        // 缺段审核 -> 422。
        mockMvc.perform(post("/api/films/" + code + "/segments")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(json(Map.of("segmentNo", 1, "contentDigest", TestData.digest("1"),
                                "requestId", "s1"))))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.versionNo").value(1))
                .andExpect(jsonPath("$.replayed").value(false));

        mockMvc.perform(post("/api/films/" + code + "/reviews")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(json(Map.of("requestId", "rv-early"))))
                .andExpect(status().isUnprocessableEntity())
                .andExpect(jsonPath("$.code").value("MISSING_SEGMENTS"));

        // 第 2 段提交；基于错误版次 -> 409。
        mockMvc.perform(post("/api/films/" + code + "/segments")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(json(Map.of("segmentNo", 2, "contentDigest", TestData.digest("2"),
                                "basedOnVersion", 5, "requestId", "s2-stale"))))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.code").value("VERSION_CONFLICT"));

        mockMvc.perform(post("/api/films/" + code + "/segments")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(json(Map.of("segmentNo", 2, "contentDigest", TestData.digest("2"),
                                "requestId", "s2"))))
                .andExpect(status().isCreated());

        // 同 requestId 异参 -> 409。
        mockMvc.perform(post("/api/films/" + code + "/segments")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(json(Map.of("segmentNo", 1, "contentDigest", TestData.digest("other"),
                                "requestId", "s1"))))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.code").value("IDEMPOTENCY_CONFLICT"));

        // 同 requestId 同参重放 -> 201 + replayed=true。
        mockMvc.perform(post("/api/films/" + code + "/segments")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(json(Map.of("segmentNo", 1, "contentDigest", TestData.digest("1"),
                                "requestId", "s1"))))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.replayed").value(true));

        // 审核通过，取母版编号。
        MvcResult reviewResult = mockMvc.perform(post("/api/films/" + code + "/reviews")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(json(Map.of("requestId", "rv"))))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.status").value("APPROVED"))
                .andExpect(jsonPath("$.segments.length()").value(2))
                .andReturn();
        JsonNode reviewBody = objectMapper.readTree(reviewResult.getResponse().getContentAsString());
        String masterNo = reviewBody.get("masterNo").asText();

        // 交付 + 重试：同一回执编号。
        MvcResult d1 = mockMvc.perform(post("/api/films/deliveries")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(json(Map.of("masterNo", masterNo, "requestId", "dv"))))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.replayed").value(false))
                .andReturn();
        String receiptNo = objectMapper.readTree(d1.getResponse().getContentAsString())
                .get("receiptNo").asText();

        mockMvc.perform(post("/api/films/deliveries")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(json(Map.of("masterNo", masterNo, "requestId", "dv"))))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.replayed").value(true))
                .andExpect(jsonPath("$.receiptNo").value(receiptNo));

        // 撤销后新交付 409，原 requestId 仍可重放。
        mockMvc.perform(post("/api/films/masters/" + masterNo + "/revoke"))
                .andExpect(status().isNoContent());
        mockMvc.perform(post("/api/films/deliveries")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(json(Map.of("masterNo", masterNo, "requestId", "dv-new"))))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.code").value("MASTER_REVOKED"));
        mockMvc.perform(post("/api/films/deliveries")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(json(Map.of("masterNo", masterNo, "requestId", "dv"))))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.receiptNo").value(receiptNo));

        // 查询：版次链、母版、回执。
        mockMvc.perform(get("/api/films/" + code))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.segmentChain.length()").value(2))
                .andExpect(jsonPath("$.masters.length()").value(1))
                .andExpect(jsonPath("$.masters[0].status").value("REVOKED"))
                .andExpect(jsonPath("$.receipts.length()").value(1))
                .andExpect(jsonPath("$.receipts[0].masterNo").value(masterNo));

        // 不存在资源 404。
        mockMvc.perform(get("/api/films/NO-SUCH-FILM"))
                .andExpect(status().isNotFound());
        mockMvc.perform(post("/api/films/deliveries")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(json(Map.of("masterNo", "M-NOPE", "requestId", "x"))))
                .andExpect(status().isNotFound());
    }
}

